export default function(){const t={plus(r,e){r=t.getPreparedMathArgs(r,e);return t.round(r.leftNum+r.rightNum,r.precision)},minus(r,e){r=t.getPreparedMathArgs(r,e);return t.round(r.leftNum-r.rightNum,r.precision)},mul(r,e){r=t.getPreparedMathArgs(r,e);return t.round(r.leftNum*r.rightNum,r.precision)},div(r,e){r=t.getPreparedMathArgs(r,e);return t.round(r.leftNum/r.rightNum,14)},mod(r,e){r=t.getPreparedMathArgs(r,e);return t.round(r.leftNum%r.rightNum,r.precision)},round(r,e=0){return Number(Math.round(Number(r+"e+"+e))+"e-"+e)},parseFloat(r,e=14){return Number(EverestFormsCalculations.parseToFloat(r,e))},getPreparedMathArgs(r,e){r=t.parseFloat(r),e=t.parseFloat(e);return{leftNum:r,rightNum:e,precision:Math.max(t.getPrecision(r),t.getPrecision(e))}},getPrecision(r){r=r.toString().split(".");return r[1]?r[1].length:0}};return{...t}}